package mx.jorge.despierta;
import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;
public final class JourneyOptions {
 static int dp(Context c,int n){return AudioOutputSettings.dp(c,n);}static TextView text(Context c,String s,int size){TextView t=new TextView(c);t.setText(s);t.setTextSize(size);t.setTextColor(VibrationEditor.color(c,"fg",Color.WHITE));t.setPadding(0,dp(c,8),0,dp(c,8));return t;}
 static void add(Context c,LinearLayout body,String s,Runnable r){Button b=AudioOutputSettings.button(c,s,false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(c,52));lp.topMargin=dp(c,8);body.addView(b,lp);b.setOnClickListener(v->r.run());}
 public static void attach(Context c,LinearLayout page,JSONObject a){add(c,page,"Aviso anticipado y activación  ›",()->show(c,a));}
 static void show(Context c,JSONObject a){Dialog d=new Dialog(c);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout body=new LinearLayout(c);body.setOrientation(1);body.setPadding(dp(c,20),dp(c,16),dp(c,20),dp(c,20));GradientDrawable bg=new GradientDrawable();bg.setColor(VibrationEditor.color(c,"surface",0xff17392e));bg.setCornerRadius(dp(c,26));body.setBackground(bg);body.addView(text(c,"Antes de llegar",23));Switch enabled=new Switch(c);enabled.setText("Aviso anticipado");enabled.setTextColor(VibrationEditor.color(c,"fg",Color.WHITE));enabled.setChecked(a.optBoolean("earlyEnabled"));body.addView(enabled);body.addView(text(c,"El aviso final conserva el radio, sonido y vibración de tu alarma.",14));body.addView(text(c,"Distancia del aviso anticipado (metros)",16));EditText radius=new EditText(c);radius.setTextColor(VibrationEditor.color(c,"fg",Color.WHITE));radius.setInputType(2);radius.setSingleLine(true);radius.setText(String.valueOf(a.optInt("earlyRadius",a.optInt("radius",1000)+500)));body.addView(radius);final int[] pattern={a.optInt("earlyPattern",1)};Button cycle=AudioOutputSettings.button(c,"Vibración: "+VibrationPattern.NAMES[Math.max(0,Math.min(3,pattern[0]))],false);body.addView(cycle);cycle.setOnClickListener(v->{pattern[0]=(pattern[0]+1)%4;cycle.setText("Vibración: "+VibrationPattern.NAMES[pattern[0]]);});Switch sound=new Switch(c);sound.setText("Sonido breve además de vibración");sound.setTextColor(VibrationEditor.color(c,"fg",Color.WHITE));sound.setChecked(a.optBoolean("earlySound"));body.addView(sound);final String[] modes={"ask","wait","now"},labels={"Preguntarme","Esperar a salir y volver a entrar","Avisar ahora"};final int[] mode={"wait".equals(a.optString("insideMode"))?1:"now".equals(a.optString("insideMode"))?2:0};body.addView(text(c,"Si al activar ya estoy dentro del radio",16));Button inside=AudioOutputSettings.button(c,labels[mode[0]],false);body.addView(inside);inside.setOnClickListener(v->{mode[0]=(mode[0]+1)%3;inside.setText(labels[mode[0]]);});add(c,body,"Aplicar",()->{try{int r=Integer.parseInt(radius.getText().toString());if(enabled.isChecked()&&(r<=a.optInt("radius",1000)||r>20000))throw new Exception();a.put("earlyEnabled",enabled.isChecked()).put("earlyRadius",r).put("earlyPattern",pattern[0]).put("earlySound",sound.isChecked()).put("insideMode",modes[mode[0]]);d.dismiss();}catch(Exception e){Toast.makeText(c,"Usa una distancia mayor que el aviso final, hasta 20 000 m",Toast.LENGTH_LONG).show();}});add(c,body,"Cancelar",()->d.dismiss());ScrollView scroll=new ScrollView(c);scroll.addView(body);d.setContentView(scroll);d.show();d.getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));d.getWindow().setGravity(Gravity.BOTTOM);d.getWindow().setLayout(-1,(int)(c.getResources().getDisplayMetrics().heightPixels*.82));}
}
